{"code":"def transform(grid):
    g=[r[:] for r in grid]
    pts={}
    for r,row in enumerate(g):
        for c,v in enumerate(row):
            if v: pts[(r,c)]=v
    if len(pts)!=3:return g
    # right isosceles configuration: apex shares column with one bottom point
    items=list(pts.items())
    apex=None; right=None; left=None
    for (p,v) in items:
        for (q,w) in items:
            if p!=q and p[1]==q[1] and p[0]<q[0]:
                rem=[x for x in items if x[0] not in (p,q)]
                if rem and rem[0][0][0]==q[0]: apex=(p,v); right=(q,w); left=rem[0]; break
        if apex: break
    if not apex:return g
    (ar,ac),av=apex; (br,bc),bv=right; (lr,lc),lv=left
    h=br-ar; w=bc-lc
    if h!=w:return g
    # interpolated internal marks
    for num,t in [(av,3/8),(5,1/2),(lv,5/8)]:
        r=round(ar+h*t); c=round(ac-w*t); g[r][c]=num
    g[br][round(bc-3*w/8)]=bv
    return g"}

